import itertools, json
jobs='ABCDE'
slot=dict(zip(jobs,[[10,7,11,4,4],[3,1,1,4,8],[5,4,5,6,2],[3,3,7,1,11],[10,9,10,1,9]]))
transfer=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def nominal(p):
    return sum(slot[j][i] for i,j in enumerate(p))+sum(transfer[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def valid(p,s):
    pos={j:p.index(j)+1 for j in jobs}
    if pos['A']>=pos['D']: return False
    return {'rain':pos['C']!=5 and pos['A']!=1,'road':pos['B']!=1 and pos['C']!=2,'lift':pos['D']!=5 and pos['B']!=5}[s]
def penalty(p,s):
    pos={j:p.index(j)+1 for j in jobs}
    return {'rain':8*max(0,pos['E']-1),'road':5*max(0,pos['D']-3),'lift':5*max(0,pos['E']-2)}[s]
results=[]
for p in itertools.permutations(jobs):
    if p.index('A')>p.index('D'): continue
    neighbors=[(p,0)]
    for i,j in itertools.combinations(range(5),2):
        q=list(p);q[i],q[j]=q[j],q[i]
        neighbors.append((tuple(q),1))
    repairs={}; costs={}
    for s in ['rain','road','lift']:
        candidates=[(nominal(q)+penalty(q,s)+exchange,''.join(q)) for q,exchange in neighbors if valid(q,s)]
        if not candidates: break
        costs[s],repairs[s]=min(candidates)
    if len(costs)==3:
        results.append((nominal(p)+max(costs.values()),''.join(p),repairs,costs))
results.sort()
best=results[0]
print(json.dumps(dict(roster=best[1],score=best[0],repairs=best[2],repair_costs=best[3],feasible_count=len(results),next_score=min(x[0] for x in results if x[0]>best[0]))))
print('best nominal',nominal(tuple(best[1])))
print('optima', [r for r in results if r[0]==best[0]])
# Independent neighborhood check using Hamming distance 0 or 2 over all legal permutations.
legal=[p for p in itertools.permutations(jobs) if p.index('A')<p.index('D')]
independent=[]
for p in legal:
    mins=[]
    for s in ['rain','road','lift']:
        vals=[nominal(q)+penalty(q,s)+(q!=p) for q in legal if sum(a!=b for a,b in zip(p,q)) in (0,2) and valid(q,s)]
        if not vals: break
        mins.append(min(vals))
    if len(mins)==3: independent.append((nominal(p)+max(mins),''.join(p)))
assert sorted((r[0],r[1]) for r in results)==sorted(independent)
print('Independent enumeration matched all feasible scores.')

