import itertools,json
jobs='ABCDE'; published='EABDC'
slot=dict(zip(jobs,[[10,7,11,4,4],[3,1,1,4,8],[5,4,5,6,2],[3,3,7,1,11],[10,9,10,1,9]]))
t=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def distance(p):
    mapping=[published.index(x) for x in p]; seen=set(); cycles=0
    for i in range(5):
        if i not in seen:
            cycles+=1; j=i
            while j not in seen:
                seen.add(j);j=mapping[j]
    return 5-cycles
classes={k:[] for k in range(3)}
for p in itertools.permutations(jobs):
    d=distance(p)
    if d>2 or p.index('A')>p.index('D') or p[4]=='C' or p[0] in ('A','E'):continue
    nominal=sum(slot[j][i] for i,j in enumerate(p))+sum(t[a][jobs.index(b)] for a,b in zip(p,p[1:]))
    cost=nominal+8*p.index('E')+d+(10 if d==2 else 0)
    classes[d].append((cost,''.join(p)))
best=min(x for group in classes.values() for x in group)
# Independently verify minimum transposition distances by breadth-first generation.
levels=[{published}]
seen={published}
for depth in range(2):
    nxt=set()
    for p in levels[-1]:
        for i,j in itertools.combinations(range(5),2):
            q=list(p);q[i],q[j]=q[j],q[i];q=''.join(q)
            if q not in seen:nxt.add(q)
    levels.append(nxt);seen.update(nxt)
for d,level in enumerate(levels):
    assert all(distance(p)==d for p in level)
    feasible={p for p in level if p.index('A')<p.index('D') and p[4]!='C' and p[0] not in ('A','E')}
    assert feasible=={p for c,p in classes[d]}
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min((v[0] for v in group),default=None) for d,group in classes.items()},'feasible_by_swaps':{str(d):len(group) for d,group in classes.items()}}))
print({d:sorted(group) for d,group in classes.items()})

